const injectedScriptSource = gunzipSync(Buffer.from(encodedInjectedScript, 'base64')).toString('utf8');
const injectedExpression = `(() => {
  if (!window.__opencuPlaywrightDomSnapshot) {
    ${injectedScriptSource}
    window.__opencuPlaywrightDomSnapshot = new PlaywrightInjected.InjectedScript(window, {
      isUnderTest: false, sdkLanguage: 'javascript', testIdAttributeName: 'data-testid',
      stableRafCount: 1, browserName: 'chromium', customEngines: [],
    });
  }
  return window.__opencuPlaywrightDomSnapshot;
})()`;

const timeoutError = () => Object.assign(new Error('Playwright DOM snapshot observation timed out.'), { name: 'TimeoutError' });

async function read(operation, signal, timeoutMs) {
  signal?.throwIfAborted();
  let timer, abort;
  const stopped = new Promise((_, reject) => {
    timer = setTimeout(() => reject(timeoutError()), Math.max(1, timeoutMs));
    if (signal) {
      abort = () => reject(signal.reason);
      signal.addEventListener('abort', abort, { once: true });
      if (signal.aborted) abort();
    }
  });
  try { return await Promise.race([Promise.resolve().then(operation), stopped]); }
  finally { clearTimeout(timer); if (abort) signal.removeEventListener('abort', abort); }
}

function captureFrame(injected, bodyOnly) {
  const root = bodyOnly ? document.body : document.body || document.documentElement;
  if (!root) {
    if (bodyOnly) throw new Error('The iframe body is unavailable.');
    return { full: '', iframeDepths: {}, iframeRefs: [] };
  }
  const snapshot = injected.incrementalAriaSnapshot(root, { mode: 'ai' });
  let full = snapshot.full;
  const iframeRefs = snapshot.iframeRefs.filter(ref => {
    if (!(ref in snapshot.iframeDepths)) return false;
    try {
      const [element] = injected.querySelectorAll(injected.parseSelector('aria-ref=' + ref), root);
      if (!element) return false;
      const id = element.getAttribute('id'), name = element.getAttribute('name');
      const attributes = [...(id ? ['[id=' + JSON.stringify(id) + ']'] : []), ...(name ? ['[name=' + JSON.stringify(name) + ']'] : [])].join(' ');
      if (attributes) full = full.replace(/^([ \t]*- iframe(?: [^\r\n]*)?) \[ref=([^\]\r\n]+)\]/gm, (line, prefix, current) => current === ref ? prefix + ' ' + attributes + ' [ref=' + ref + ']' : line);
      return element.getAttribute('aria-hidden') !== 'true' && injected.elementState(element, 'visible').matches === true;
    } catch { return false; }
  });
  return { ...snapshot, full, iframeRefs };
}

const iframeReference = line => line.trimStart().startsWith('- iframe') ? line.match(/\[ref=([^\]]+)\]/)?.[1] ?? null : null;

export function cleanDomSnapshot(text) {
  if (!text.startsWith('- ') && !text.includes('\n- ') && !text.includes('\n  - ')) return text;
  const root = { children: [], indent: -1, line: '' }, stack = [root];
  for (const line of text.split('\n')) {
    if (!line.trim()) continue;
    const indent = line.match(/^ */)?.[0].length ?? 0;
    const node = { children: [], indent, line: line.slice(indent) };
    while (stack.length > 1 && indent <= stack.at(-1).indent) stack.pop();
    stack.at(-1).children.push(node); stack.push(node);
  }
  const filter = node => {
    const children = node.children.flatMap(filter);
    const line = node.line.replace(/ \[ref=[^\]]+\]/g, '').replace(/ \[cursor=[^\]]+\]/g, '');
    if (/^- img(?: \[[^\]]+\])*:?$/.test(line)) return [];
    if (/^- (generic|listitem|group)(?: \[[^\]]+\])*:?$/.test(line)) return children;
    return [{ line, children }];
  };
  const render = (nodes, depth = 0) => {
    const lines = [], prefix = '  '.repeat(depth);
    for (const node of nodes) {
      lines.push(prefix + node.line);
      const nested = render(node.children, depth + 1);
      if (nested) lines.push(nested);
    }
    return lines.join('\n');
  };
  return render(root.children.flatMap(filter));
}

export async function browserDomSnapshot(record, signal, { documentOnly = false, isIabBackend = false } = {}) {
  signal?.throwIfAborted();
  const injectedByFrame = new Map();
  let closed = false;
  const injectedFor = async (frame, timeoutMs) => {
    signal?.throwIfAborted();
    if (closed) throw new Error('Playwright DOM snapshot observation closed.');
    let pending = injectedByFrame.get(frame);
    if (!pending) {
      pending = frame.evaluateHandle(injectedExpression);
      injectedByFrame.set(frame, pending);
    }
    return read(() => pending, signal, timeoutMs);
  };
  const snapshot = async (frame, timeoutMs, bodyOnly) => {
    const deadline = Date.now() + timeoutMs;
    const injected = await injectedFor(frame, timeoutMs);
    return read(() => injected.evaluate(captureFrame, bodyOnly), signal, Math.max(1, deadline - Date.now()));
  };
  const expand = async (frame, data, deadline) => {
    const refs = data.iframeRefs.filter(ref => ref in data.iframeDepths);
    if (!refs.length || deadline !== undefined && Date.now() >= deadline) return data.full;
    const children = new Map(await Promise.all(refs.map(async ref => {
      let element, pendingElement;
      try {
        signal?.throwIfAborted();
        if (deadline !== undefined && Date.now() >= deadline) return [ref, null];
        const timeoutMs = deadline === undefined ? 3000 : Math.max(1, Math.min(3000, 500, deadline - Date.now()));
        const stepDeadline = Date.now() + timeoutMs;
        const remaining = () => { const milliseconds = stepDeadline - Date.now(); if (milliseconds <= 0) throw timeoutError(); return milliseconds; };
        const injected = await injectedFor(frame, remaining());
        pendingElement = injected.evaluateHandle((engine, current) => {
          const root = document.body || document.documentElement;
          return root ? engine.querySelectorAll(engine.parseSelector('aria-ref=' + current), root)[0] : null;
        }, ref);
        element = await read(() => pendingElement, signal, remaining());
        const child = await read(() => element.asElement()?.contentFrame(), signal, remaining());
        if (!child) return [ref, null];
        const captured = await snapshot(child, remaining(), true);
        return [ref, await expand(child, captured, deadline)];
      } catch { signal?.throwIfAborted(); return [ref, null]; }
      finally { if (pendingElement) void pendingElement.then(handle => handle.dispose()).catch(() => {}); }
    })));
    const lines = [];
    for (const line of data.full.split('\n')) {
      const ref = iframeReference(line), child = ref && children.get(ref);
      if (!child) { lines.push(line); continue; }
      const indent = line.match(/^ */)?.[0] ?? '';
      lines.push(line.endsWith(':') ? line : line + ':');
      lines.push(...child.split('\n').map(nested => indent + '  ' + nested));
    }
    return lines.join('\n');
  };
  try {
    const frame = record.page.mainFrame(), data = await snapshot(frame, 3000, false);
    const full = documentOnly ? data.full : await expand(frame, data, isIabBackend ? Date.now() + 1000 : undefined);
    signal?.throwIfAborted();
    return cleanDomSnapshot(full);
  } finally {
    closed = true;
    for (const pending of injectedByFrame.values()) void pending.then(handle => handle.dispose()).catch(() => {});
  }
}
